const crypto = require('crypto');
// Create approval request with risk evaluation and explainability metadata
const webhook = $('Approval Request').item.json;
const body = webhook.body || webhook;
const riskEval = $input.item.json; // output of Evaluate Risk node

const actionDescription = body.action_description || '';
const severity = (body.severity || 'high').toLowerCase();
const context = body.context || {};
const timeoutHours = body.timeout_hours || 4;
const source = body.source || 'dirigent';
const agentSlug = body.agent_slug || source;
const category = body.category || 'function';
const requestReasoning = body.decision_reasoning || '';

if (!actionDescription) {
  return [{ json: { error: true, message: 'Missing required field: action_description' } }];
}

// Ground-truth risk from DB fn_evaluate_proposal_risk (independent of caller-declared severity)
const computedRisk = (riskEval && !riskEval.error && riskEval.data)
  ? String(riskEval.data).toLowerCase()
  : severity;

// Context hash for audit correlation and deduplication
const contextStr = actionDescription + '|' + agentSlug + '|' + category + '|' + JSON.stringify(context);
let h = 0;
for (let i = 0; i < contextStr.length; i++) { h = ((h << 5) - h) + contextStr.charCodeAt(i); h |= 0; }
const contextHash = Math.abs(h).toString(16).padStart(8, '0');

// Criteria evaluation for explainability
const criteriaMet = [];
const criteriaFailed = [];

if (computedRisk === severity) criteriaMet.push('risk_severity_consistent');
else criteriaFailed.push('risk_mismatch:declared=' + severity + ',computed=' + computedRisk);

if (requestReasoning) criteriaMet.push('decision_reasoning_provided');
else criteriaFailed.push('decision_reasoning_missing');

if (Object.keys(context).length > 0) criteriaMet.push('context_provided');
else criteriaFailed.push('context_empty');

if (['critical', 'high'].includes(computedRisk)) criteriaMet.push('high_risk_gate_required');

const approvalId = 'approval_' + Date.now() + '_' + Math.random().toString(36).substr(2, 8);
const createdAt = new Date();
const expiresAt = new Date(createdAt.getTime() + timeoutHours * 60 * 60 * 1000);
const baseUrl = $env && $env.N8N_URL ? $env.N8N_URL : '';

const _linkSecret = ($env && $env.APPROVAL_LINK_HMAC_SECRET) || '';
const _signLink = (dec) => crypto.createHmac('sha256', _linkSecret).update(approvalId + '|' + dec + '|' + expiresAt.toISOString()).digest('hex');
return [{
  json: {
    error: false,
    approvalId,
    actionDescription,
    severity,
    computedRisk,
    riskScore: computedRisk,
    context,
    source,
    agentSlug,
    category,
    timeoutHours,
    createdAt: createdAt.toISOString(),
    expiresAt: expiresAt.toISOString(),
    status: 'pending',
    contextHash,
    criteriaMet,
    criteriaFailed,
    decisionReasoning: requestReasoning,
    approvalUrl: baseUrl + '/webhook/approval-response',
    approveLink: baseUrl + '/webhook/approval-response?id=' + approvalId + '&decision=approved&expires=' + encodeURIComponent(expiresAt.toISOString()) + '&sig=' + _signLink('approved'),
    rejectLink: baseUrl + '/webhook/approval-response?id=' + approvalId + '&decision=rejected&expires=' + encodeURIComponent(expiresAt.toISOString()) + '&sig=' + _signLink('rejected')
  }
}];

// Store approval request in NocoDB for tracking
// Also return the approval details for the caller
const input = $('Create Approval Request').item.json;

return [{
  json: {
    success: true,
    approvalId: input.approvalId,
    status: 'pending',
    actionDescription: input.actionDescription,
    severity: input.severity,
    expiresAt: input.expiresAt,
    approveLink: input.approveLink,
    rejectLink: input.rejectLink,
    message: `Approval request created. Expert has been notified. Timeout: ${input.timeoutHours}h.`
  }
}];

const crypto = require('crypto');
// Process approval response from expert with expiry check
const query = $input.item.json.query || {};
const approvalId = query.id || '';
let decision = (query.decision || '').toLowerCase();
const comment = query.comment || '';
const expiresAtStr = query.expires || '';

if (!approvalId || !decision) {
  return [{ json: { error: true, message: 'Missing required params: id, decision (approved/rejected)', html: '<html><body><h2>Invalid Request</h2><p>Missing approval ID or decision.</p></body></html>' } }];
}

// N8N-03 signed-link HMAC verification — a forged/guessed approval link is rejected.
const _sig = query.sig || '';
const _linkSecret = ($env && $env.APPROVAL_LINK_HMAC_SECRET) || '';
const _expectedSig = crypto.createHmac('sha256', _linkSecret).update(approvalId + '|' + decision + '|' + expiresAtStr).digest('hex');
let _sigValid = false;
try { _sigValid = _sig.length === _expectedSig.length && crypto.timingSafeEqual(Buffer.from(_sig), Buffer.from(_expectedSig)); } catch (e) { _sigValid = false; }
if (!_sigValid) { return [{ json: { error: true, message: 'Invalid or missing approval-link signature', html: '<html><body><h2>Invalid Request</h2><p>The approval link signature is invalid.</p></body></html>' } }]; }

// Expiry check: approve/reject links carry expires= query param
if (expiresAtStr) {
  try {
    const expiresAt = new Date(decodeURIComponent(expiresAtStr));
    if (!isNaN(expiresAt.getTime()) && new Date() > expiresAt) { decision = 'expired'; }
  } catch (e) { /* ignore malformed expiry */ }
}

if (!['approved', 'rejected', 'expired'].includes(decision)) {
  return [{ json: { error: true, message: `Invalid decision: ${decision}. Must be 'approved' or 'rejected'.`, html: '<html><body><h2>Invalid Decision</h2><p>Decision must be "approved" or "rejected".</p></body></html>' } }];
}

const isExpired = decision === 'expired';
const respondedBy = isExpired ? 'system_timeout' : 'expert';

return [{
  json: {
    error: false,
    approvalId,
    decision,
    comment,
    respondedAt: new Date().toISOString(),
    respondedBy,
    decisionReasoning: comment || (isExpired ? 'Approval request timeout exceeded - auto-escalated to CRITICAL' : ''),
    criteriaMet: isExpired ? [] : ['human_decision_recorded'],
    criteriaFailed: isExpired ? ['approval_timeout'] : [],
    isExpired
  }
}];

// Generate human-friendly response page
const decision = $('Process Response').item.json.decision;
const approvalId = $('Process Response').item.json.approvalId;
const emoji = decision === 'approved' ? '✅' : '❌';
const title = decision === 'approved' ? 'Approved' : 'Rejected';
const color = decision === 'approved' ? '#22c55e' : '#ef4444';

return [{
  json: {
    html: `<html><head><style>body{font-family:system-ui;max-width:600px;margin:60px auto;text-align:center;background:#f8fafc;color:#1e293b}h1{color:${color};font-size:3em}p{font-size:1.2em;color:#64748b}.id{font-family:monospace;color:#94a3b8;font-size:0.9em}</style></head><body><h1>${emoji} ${title}</h1><p>Your decision has been recorded and forwarded to AISHA Dirigent.</p><p class='id'>Approval ID: ${approvalId}</p></body></html>`
  }
}];
